<main id="main" class="main">
    <div class="pagetitle"><p class="admin-eyebrow">Admissions</p><h1>Dossiers étudiants</h1><p>Consultation des demandes déposées et de leurs pièces jointes.</p></div>
    <section class="section">
        <div class="alert alert-info" role="note">Cet écran permet de consulter les dossiers. Les statuts historiques ne sont pas modifiés ici, car leurs règles de validation doivent être confirmées par l’établissement.</div>
        <div class="card"><div class="card-body">
            <form method="get" class="row g-2 mb-4"><input type="hidden" name="pages" value="candidatures"><div class="col-sm-8 col-md-6"><label class="visually-hidden" for="candidate-search">Rechercher un dossier étudiant</label><input class="form-control" id="candidate-search" name="q" value="<?= htmlspecialchars($candidateSearch, ENT_QUOTES, 'UTF-8') ?>" placeholder="Nom, matricule, téléphone ou e-mail"></div><div class="col-auto"><button class="btn btn-primary" type="submit">Rechercher</button></div></form>
            <div class="table-responsive"><table class="table align-middle"><thead><tr><th>Candidat</th><th>Matricule</th><th>Choix de formation</th><th>Dépôt</th><th>Dossier</th><th>Actions</th></tr></thead><tbody>
                <?php foreach ($candidates as $candidate): ?>
                    <tr><td><strong><?= htmlspecialchars(trim($candidate['prenom'] . ' ' . $candidate['nom'] . ' ' . $candidate['postnom']), ENT_QUOTES, 'UTF-8') ?></strong><br><small><?= htmlspecialchars((string) $candidate['telephone'], ENT_QUOTES, 'UTF-8') ?><?= $candidate['email'] ? ' · ' . htmlspecialchars((string) $candidate['email'], ENT_QUOTES, 'UTF-8') : '' ?></small><details class="mt-1"><summary>Pièces du dossier</summary><div class="d-flex flex-wrap gap-2 mt-2"><?php foreach (['diplomeAttest' => 'Diplôme', 'certificat' => 'Certificat', 'bulletin' => 'Bulletin', 'carteIdentite' => 'Pièce d’identité', 'attestNaissance' => 'Attestation de naissance'] as $document => $label): ?><a class="btn btn-sm btn-outline-secondary" href="download.php?id=<?= (int) $candidate['id'] ?>&amp;document=<?= rawurlencode($document) ?>"><?= htmlspecialchars($label, ENT_QUOTES, 'UTF-8') ?></a><?php endforeach; ?></div></details></td><td><?= htmlspecialchars((string) $candidate['matricule'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($candidate['fac1_titre'] ?? ''), ENT_QUOTES, 'UTF-8') ?><br><small><?= htmlspecialchars((string) ($candidate['dep1_titre'] ?? ''), ENT_QUOTES, 'UTF-8') ?></small><?php if (!empty($candidate['fac2_titre']) || !empty($candidate['dep2_titre'])): ?><br><span class="text-muted">Second choix : <?= htmlspecialchars((string) ($candidate['fac2_titre'] ?? ''), ENT_QUOTES, 'UTF-8') ?> · <?= htmlspecialchars((string) ($candidate['dep2_titre'] ?? ''), ENT_QUOTES, 'UTF-8') ?></span><?php endif; ?></td><td><?= htmlspecialchars((string) $candidate['date_inscrit'], ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $candidate['confirmer'] === 1 ? 'Confirmé (indicateur historique)' : 'Non confirmé (indicateur historique)' ?></td><td><form method="post" onsubmit="return confirm('Supprimer définitivement ce dossier étudiant et ses pièces non partagées ?');"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="record_id" value="<?= (int) $candidate['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit" name="admin_action" value="delete"><i class="bi bi-trash me-1" aria-hidden="true"></i> Supprimer</button></form></td></tr>
                <?php endforeach; ?>
            </tbody></table></div>
            <?php if (!$candidates): ?><p class="admin-empty-state">Aucun dossier trouvé.</p><?php endif; ?>
            <?php if ($candidatePages > 1): ?><nav aria-label="Pagination des candidatures"><ul class="pagination flex-wrap">
                <li class="page-item <?= $candidatePage === 1 ? 'disabled' : '' ?>"><a class="page-link" href="?pages=candidatures&amp;pag=<?= max(1, $candidatePage - 1) ?>&amp;q=<?= rawurlencode($candidateSearch) ?>" aria-label="Page précédente">Précédent</a></li>
                <?php if ($candidateWindowStart > 1): ?><li class="page-item"><a class="page-link" href="?pages=candidatures&amp;pag=1&amp;q=<?= rawurlencode($candidateSearch) ?>">1</a></li><?php if ($candidateWindowStart > 2): ?><li class="page-item disabled"><span class="page-link">…</span></li><?php endif; ?><?php endif; ?>
                <?php for ($p = $candidateWindowStart; $p <= $candidateWindowEnd; $p++): ?><li class="page-item <?= $p === $candidatePage ? 'active' : '' ?>"><a class="page-link" href="?pages=candidatures&amp;pag=<?= $p ?>&amp;q=<?= rawurlencode($candidateSearch) ?>" <?= $p === $candidatePage ? 'aria-current="page"' : '' ?>><?= $p ?></a></li><?php endfor; ?>
                <?php if ($candidateWindowEnd < $candidatePages): ?><?php if ($candidateWindowEnd < $candidatePages - 1): ?><li class="page-item disabled"><span class="page-link">…</span></li><?php endif; ?><li class="page-item"><a class="page-link" href="?pages=candidatures&amp;pag=<?= $candidatePages ?>&amp;q=<?= rawurlencode($candidateSearch) ?>"><?= $candidatePages ?></a></li><?php endif; ?>
                <li class="page-item <?= $candidatePage === $candidatePages ? 'disabled' : '' ?>"><a class="page-link" href="?pages=candidatures&amp;pag=<?= min($candidatePages, $candidatePage + 1) ?>&amp;q=<?= rawurlencode($candidateSearch) ?>" aria-label="Page suivante">Suivant</a></li>
            </ul></nav><?php endif; ?>
        </div></div>
    </section>
</main>
